/**
 * Meri — database schema (source of truth).
 * Rules (see docs/03-data-model.md):
 *  - Every domain table has workspace_id NOT NULL (+ RLS policy added via SQL migration).
 *  - Suggested data lives in `proposals`; confirmed data lives in domain tables.
 *  - No email bodies are stored. Only ids, minimal metadata and a short cited snippet.
 *  - IDs are UUIDs generated by the application (prefer UUIDv7).
 */
import { sql } from "drizzle-orm";
import {
  pgTable,
  pgEnum,
  uuid,
  text,
  timestamp,
  integer,
  boolean,
  jsonb,
  real,
  bigint,
  date,
  index,
  uniqueIndex,
  primaryKey,
} from "drizzle-orm/pg-core";

// ---------- Enums ----------
export const taskStatus = pgEnum("task_status", [
  "pending",
  "scheduled",
  "in_progress",
  "blocked",
  "waiting_on_third_party",
  "at_risk",
  "completed",
]);
export const taskKind = pgEnum("task_kind", ["deep", "shallow"]);
export const deadlineType = pgEnum("deadline_type", ["soft", "hard"]);
export const origin = pgEnum("origin", ["user", "ai_confirmed", "system", "integration"]);
export const commitmentDirection = pgEnum("commitment_direction", ["owed_by_me", "owed_to_me"]);
export const commitmentKind = pgEnum("commitment_kind", ["explicit", "inferred", "suggested"]);
export const commitmentStatus = pgEnum("commitment_status", [
  "proposed",
  "confirmed",
  "fulfilled",
  "at_risk",
  "broken",
  "dismissed",
]);
export const proposalKind = pgEnum("proposal_kind", [
  "capture",
  "commitment",
  "followup",
  "reschedule",
  "time_entry",
  "client_link",
]);
export const proposalStatus = pgEnum("proposal_status", [
  "pending",
  "confirmed",
  "edited",
  "dismissed",
  "expired",
]);
export const provider = pgEnum("provider", ["google", "microsoft", "notion", "slack"]);
export const connectionStatus = pgEnum("connection_status", [
  "healthy",
  "needs_reauth",
  "degraded",
  "paused",
  "revoked",
]);
export const auditActor = pgEnum("audit_actor", ["user", "system", "ai"]);
export const blockOrigin = pgEnum("block_origin", ["meri", "external"]);
export const timeEntryStatus = pgEnum("time_entry_status", ["suggested", "approved", "rejected", "exported"]);
export const autonomyLevel = pgEnum("autonomy_level", ["suggest_only", "auto_low_risk"]);

// ---------- Helpers ----------
const id = () => uuid("id").primaryKey();
const workspaceId = () =>
  uuid("workspace_id")
    .notNull()
    .references(() => workspaces.id, { onDelete: "cascade" });
const createdAt = () => timestamp("created_at", { withTimezone: true }).notNull().defaultNow();
const updatedAt = () => timestamp("updated_at", { withTimezone: true }).notNull().defaultNow();
const deletedAt = () => timestamp("deleted_at", { withTimezone: true });

// ---------- Identity & tenancy ----------
export const users = pgTable(
  "users",
  {
    id: id(),
    email: text("email").notNull(),
    name: text("name"),
    image: text("image"),
    locale: text("locale").notNull().default("es"),
    /** Identity at the provider (`google:<sub>`, `dev:<email>` in development); a recycled address never inherits. */
    authSubject: text("auth_subject"),
    /** Sessions authenticated before this instant are refused («sign out on all devices», ADR 0007). */
    sessionsValidAfter: timestamp("sessions_valid_after", { withTimezone: true }),
    createdAt: createdAt(),
    deletedAt: deletedAt(),
  },
  (t) => [uniqueIndex("users_email_uq").on(t.email), uniqueIndex("users_auth_subject_uq").on(t.authSubject)],
);

export const workspaces = pgTable("workspaces", {
  id: id(),
  name: text("name").notNull(),
  ownerId: uuid("owner_id").notNull(),
  vertical: text("vertical"), // 'legal' | 'consulting' | 'generic'
  createdAt: createdAt(),
  deletedAt: deletedAt(),
});

export const memberships = pgTable(
  "memberships",
  {
    workspaceId: workspaceId(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    role: text("role").notNull().default("owner"), // owner | admin | member
    createdAt: createdAt(),
  },
  (t) => [primaryKey({ columns: [t.workspaceId, t.userId] })],
);

export const preferences = pgTable("preferences", {
  workspaceId: workspaceId().primaryKey(),
  timezone: text("timezone").notNull().default("UTC"),
  workStart: text("work_start").notNull().default("09:00"),
  workEnd: text("work_end").notNull().default("18:00"),
  workDays: jsonb("work_days").$type<number[]>().notNull().default([1, 2, 3, 4, 5]),
  deepWorkWindows: jsonb("deep_work_windows").$type<{ start: string; end: string }[]>().notNull().default([]),
  minBlockMinutes: integer("min_block_minutes").notNull().default(30),
  minDeepBlockMinutes: integer("min_deep_block_minutes").notNull().default(90),
  bufferMinutes: integer("buffer_minutes").notNull().default(10),
  contingencyPct: integer("contingency_pct").notNull().default(20),
  riskThresholdHours: integer("risk_threshold_hours").notNull().default(4),
  maxAlertsPerDay: integer("max_alerts_per_day").notNull().default(5),
  autonomy: autonomyLevel("autonomy").notNull().default("suggest_only"),
  timeRoundingMinutes: integer("time_rounding_minutes").notNull().default(6),
  /** Set when the user completes onboarding (F-01). Null = must onboard. */
  onboardedAt: timestamp("onboarded_at", { withTimezone: true }),
  /** Explicit plan version (ADR 0003): bumped in the same transaction as every plan change, restored on undo. */
  planVersion: integer("plan_version").notNull().default(0),
  /** D-034: auto-confirm explicit, high-confidence commitments (off by default). */
  gmailAutoconfirm: boolean("gmail_autoconfirm").notNull().default(false),
  /** D-035: days without reply before a follow-up is proposed. */
  followupDays: integer("followup_days").notNull().default(3),
  /** docs/06 §5: retention of dismissed proposals and snippets, in days. */
  retentionDays: integer("retention_days").notNull().default(90),
  /** D-045: vertical template chosen in onboarding (legal | consulting | generic). */
  vertical: text("vertical").$type<"legal" | "consulting" | "generic">().notNull().default("generic"),
  /** D-043: notify one day before a client meeting so the briefing can be opened (notification only, no task). */
  briefingBeforeMeetings: boolean("briefing_before_meetings").notNull().default(true),
  updatedAt: updatedAt(),
});

// ---------- Clients & projects ----------
export const clients = pgTable(
  "clients",
  {
    id: id(),
    workspaceId: workspaceId(),
    name: text("name").notNull(),
    domains: jsonb("domains").$type<string[]>().notNull().default([]),
    color: text("color"),
    /** F-08 AC2: no follow-up proposals for this client. */
    followupsMuted: boolean("followups_muted").notNull().default(false),
    /** Phase 3 (D-039/D-045): free notes and vertical template tags ("litigio", "fiscal", …). */
    notes: text("notes"),
    verticalTags: jsonb("vertical_tags").$type<string[]>().notNull().default([]),
    archivedAt: timestamp("archived_at", { withTimezone: true }),
    createdAt: createdAt(),
    deletedAt: deletedAt(),
  },
  (t) => [index("clients_ws_idx").on(t.workspaceId)],
);

export const projects = pgTable(
  "projects",
  {
    id: id(),
    workspaceId: workspaceId(),
    clientId: uuid("client_id").references(() => clients.id),
    name: text("name").notNull(),
    /** Matter type from the vertical template (D-045), free text. */
    kind: text("kind"),
    dueAt: timestamp("due_at", { withTimezone: true }),
    status: text("status").notNull().default("active"),
    createdAt: createdAt(),
    deletedAt: deletedAt(),
  },
  (t) => [index("projects_ws_client_idx").on(t.workspaceId, t.clientId)],
);

export const contacts = pgTable(
  "contacts",
  {
    id: id(),
    workspaceId: workspaceId(),
    clientId: uuid("client_id").references(() => clients.id),
    email: text("email").notNull(),
    name: text("name"),
    muted: boolean("muted").notNull().default(false),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex("contacts_ws_email_uq").on(t.workspaceId, t.email)],
);

// ---------- Tasks ----------
export const tasks = pgTable(
  "tasks",
  {
    id: id(),
    workspaceId: workspaceId(),
    clientId: uuid("client_id").references(() => clients.id),
    projectId: uuid("project_id").references(() => projects.id),
    parentId: uuid("parent_id"),
    title: text("title").notNull(),
    notes: text("notes"),
    status: taskStatus("status").notNull().default("pending"),
    kind: taskKind("kind").notNull().default("shallow"),
    priority: integer("priority").notNull().default(3), // 1 (highest) .. 4
    dueAt: timestamp("due_at", { withTimezone: true }),
    deadlineType: deadlineType("deadline_type").notNull().default("soft"),
    estimateMinutes: integer("estimate_minutes"),
    tags: jsonb("tags").$type<string[]>().notNull().default([]),
    /** Rule-computed risk (D-022). Null = no risk. */
    risk: jsonb("risk").$type<{
      cause: "LOW_SLACK" | "BLOCKED_DEPENDENCY" | "NO_CAPACITY";
      slackHours: number;
      since: string;
    } | null>(),
    origin: origin("origin").notNull().default("user"),
    sourceCommitmentId: uuid("source_commitment_id"),
    completedAt: timestamp("completed_at", { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    deletedAt: deletedAt(),
  },
  (t) => [
    index("tasks_ws_status_due_idx").on(t.workspaceId, t.status, t.dueAt),
    index("tasks_ws_client_idx").on(t.workspaceId, t.clientId),
  ],
);

export const taskDependencies = pgTable(
  "task_dependencies",
  {
    workspaceId: workspaceId(),
    taskId: uuid("task_id")
      .notNull()
      .references(() => tasks.id, { onDelete: "cascade" }),
    blockedByTaskId: uuid("blocked_by_task_id")
      .notNull()
      .references(() => tasks.id, { onDelete: "cascade" }),
  },
  (t) => [primaryKey({ columns: [t.taskId, t.blockedByTaskId] })],
);

// ---------- Calendar & schedule ----------
export const calendarEvents = pgTable(
  "calendar_events",
  {
    id: id(),
    workspaceId: workspaceId(),
    integrationAccountId: uuid("integration_account_id"),
    // Google event ids are unique per calendar, not per account (ADR 0008).
    calendarId: text("calendar_id").notNull().default("primary"),
    externalId: text("external_id").notNull(),
    etag: text("etag"),
    title: text("title"),
    startsAt: timestamp("starts_at", { withTimezone: true }).notNull(),
    endsAt: timestamp("ends_at", { withTimezone: true }).notNull(),
    allDay: boolean("all_day").notNull().default(false),
    attendees: jsonb("attendees").$type<string[]>().notNull().default([]),
    clientId: uuid("client_id").references(() => clients.id),
    origin: blockOrigin("origin").notNull().default("external"),
    busy: boolean("busy").notNull().default(true),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("cal_events_ext_uq").on(t.workspaceId, t.integrationAccountId, t.calendarId, t.externalId),
    index("cal_events_ws_start_idx").on(t.workspaceId, t.startsAt),
    index("cal_events_ws_client_start_idx").on(t.workspaceId, t.clientId, t.startsAt),
  ],
);

export const scheduleBlocks = pgTable(
  "schedule_blocks",
  {
    id: id(),
    workspaceId: workspaceId(),
    taskId: uuid("task_id")
      .notNull()
      .references(() => tasks.id, { onDelete: "cascade" }),
    startsAt: timestamp("starts_at", { withTimezone: true }).notNull(),
    endsAt: timestamp("ends_at", { withTimezone: true }).notNull(),
    pinned: boolean("pinned").notNull().default(false),
    reason: jsonb("reason")
      .$type<{ code: string; params: Record<string, unknown> }[]>()
      .notNull()
      .default([]),
    calendarEventId: uuid("calendar_event_id"),
    planVersion: integer("plan_version").notNull().default(1),
    /** Marked by the user as done (feeds time inference in phase 3). */
    completedAt: timestamp("completed_at", { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [index("blocks_ws_start_idx").on(t.workspaceId, t.startsAt)],
);

// ---------- Mail index (minimal; NO bodies) ----------
export const threadsIndex = pgTable(
  "threads_index",
  {
    id: id(),
    workspaceId: workspaceId(),
    integrationAccountId: uuid("integration_account_id").notNull(),
    externalThreadId: text("external_thread_id").notNull(),
    subject: text("subject"),
    participants: jsonb("participants").$type<string[]>().notNull().default([]),
    clientId: uuid("client_id").references(() => clients.id),
    lastMessageAt: timestamp("last_message_at", { withTimezone: true }),
    lastMessageFromMe: boolean("last_message_from_me"),
    /** Id of the newest message (threading for drafts); never its content. */
    lastExternalMessageId: text("last_external_message_id"),
    processedAt: timestamp("processed_at", { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("threads_ext_uq").on(t.workspaceId, t.integrationAccountId, t.externalThreadId),
    index("threads_ws_client_last_idx").on(t.workspaceId, t.clientId, t.lastMessageAt),
  ],
);

// ---------- Commitments & proposals ----------
export const commitments = pgTable(
  "commitments",
  {
    id: id(),
    workspaceId: workspaceId(),
    clientId: uuid("client_id").references(() => clients.id),
    direction: commitmentDirection("direction").notNull(),
    kind: commitmentKind("kind").notNull(),
    status: commitmentStatus("status").notNull().default("proposed"),
    counterpartyEmail: text("counterparty_email"),
    action: text("action").notNull(),
    dueAt: timestamp("due_at", { withTimezone: true }),
    dueText: text("due_text"),
    confidence: real("confidence"),
    evidence: text("evidence"), // <= 200 chars, verified to exist in source
    threadId: uuid("thread_id").references(() => threadsIndex.id),
    externalMessageId: text("external_message_id"),
    dedupeHash: text("dedupe_hash").notNull(),
    taskId: uuid("task_id"),
    origin: origin("origin").notNull().default("ai_confirmed"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("commitments_dedupe_uq").on(t.workspaceId, t.dedupeHash),
    index("commitments_ws_dir_status_idx").on(t.workspaceId, t.direction, t.status, t.dueAt),
  ],
);

export const proposals = pgTable(
  "proposals",
  {
    id: id(),
    workspaceId: workspaceId(),
    kind: proposalKind("kind").notNull(),
    status: proposalStatus("status").notNull().default("pending"),
    payload: jsonb("payload").$type<Record<string, unknown>>().notNull(),
    confidence: real("confidence"),
    explanation: text("explanation"),
    sourceRef: jsonb("source_ref").$type<{ type: string; id: string; url?: string }>(),
    resolution: jsonb("resolution").$type<{ action: string; editedPayload?: Record<string, unknown> }>(),
    resolvedAt: timestamp("resolved_at", { withTimezone: true }),
    /** Optional dedupe key: at most one PENDING proposal per hash (F-08 AC1 "una única alerta"). */
    dedupeHash: text("dedupe_hash"),
    /** First time the proposal was listed to the user (analytics `proposal_shown` once per proposal, [M9]). */
    shownAt: timestamp("shown_at", { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [
    index("proposals_ws_status_idx").on(t.workspaceId, t.status, t.createdAt),
    uniqueIndex("proposals_pending_dedupe_uq")
      .on(t.workspaceId, t.dedupeHash)
      .where(sql`${t.status} = 'pending' and ${t.dedupeHash} is not null`),
  ],
);

// ---------- Time ----------
export const timeEntries = pgTable(
  "time_entries",
  {
    id: id(),
    workspaceId: workspaceId(),
    clientId: uuid("client_id").references(() => clients.id),
    projectId: uuid("project_id").references(() => projects.id),
    taskId: uuid("task_id").references(() => tasks.id),
    day: date("day").notNull(),
    minutes: integer("minutes").notNull(),
    description: text("description"),
    status: timeEntryStatus("status").notNull().default("suggested"),
    sourceType: text("source_type").notNull(), // 'calendar_event' | 'schedule_block' | 'manual'
    sourceId: uuid("source_id"),
    createdAt: createdAt(),
    approvedAt: timestamp("approved_at", { withTimezone: true }),
  },
  (t) => [
    index("time_ws_day_idx").on(t.workspaceId, t.day),
    index("time_ws_client_day_idx").on(t.workspaceId, t.clientId, t.day),
    // D-042: one entry per inferred source; re-inference is idempotent.
    uniqueIndex("time_entries_source_uq")
      .on(t.workspaceId, t.sourceType, t.sourceId)
      .where(sql`${t.sourceId} is not null`),
  ],
);

/** D-043: last generated briefing per client (and optionally per meeting); items carry their source ids. */
export const briefings = pgTable(
  "briefings",
  {
    id: id(),
    workspaceId: workspaceId(),
    clientId: uuid("client_id")
      .notNull()
      .references(() => clients.id, { onDelete: "cascade" }),
    eventId: uuid("event_id"),
    items: jsonb("items")
      .$type<
        { claim: string; kind: string; sourceType: string; sourceId: string; url?: string; sourceTitle?: string }[]
      >()
      .notNull()
      .default([]),
    /** Hash of the client snapshot the briefing was built from: unchanged → reuse (< 10 s, F-11 AC1). */
    sourceHash: text("source_hash").notNull(),
    source: text("source").notNull().default("rules"), // 'rules' | 'ai'
    generatedAt: timestamp("generated_at", { withTimezone: true }).notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    // One client-level briefing and one per meeting (NULLs are distinct in a plain unique index).
    uniqueIndex("briefings_ws_client_uq")
      .on(t.workspaceId, t.clientId)
      .where(sql`${t.eventId} is null`),
    uniqueIndex("briefings_ws_client_event_uq")
      .on(t.workspaceId, t.clientId, t.eventId)
      .where(sql`${t.eventId} is not null`),
  ],
);

// ---------- Integrations ----------
export const integrationAccounts = pgTable(
  "integration_accounts",
  {
    id: id(),
    workspaceId: workspaceId(),
    provider: provider("provider").notNull(),
    externalAccountId: text("external_account_id").notNull(),
    email: text("email"),
    scopes: jsonb("scopes").$type<string[]>().notNull().default([]),
    status: connectionStatus("status").notNull().default("healthy"),
    // Envelope encryption: ciphertext blobs, never plaintext tokens.
    encryptedTokens: text("encrypted_tokens").notNull(),
    keyId: text("key_id").notNull(),
    lastSyncAt: timestamp("last_sync_at", { withTimezone: true }),
    lastError: text("last_error"),
    /** The dedicated «Meri» calendar, created once and the only one Meri writes to (ADR 0008). */
    meriCalendarId: text("meri_calendar_id"),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex("integ_ws_provider_acct_uq").on(t.workspaceId, t.provider, t.externalAccountId)],
);

export const syncState = pgTable(
  "sync_state",
  {
    workspaceId: workspaceId(),
    integrationAccountId: uuid("integration_account_id")
      .notNull()
      .references(() => integrationAccounts.id, { onDelete: "cascade" }),
    resource: text("resource").notNull(), // 'gmail.history' | 'calendar.events' | ...
    cursor: text("cursor"),
    channelId: text("channel_id"),
    channelExpiresAt: timestamp("channel_expires_at", { withTimezone: true }),
    updatedAt: updatedAt(),
  },
  (t) => [primaryKey({ columns: [t.integrationAccountId, t.resource] })],
);

// ---------- Audit, AI usage, value ----------
export const auditLog = pgTable(
  "audit_log",
  {
    id: id(),
    workspaceId: workspaceId(),
    actor: auditActor("actor").notNull(),
    actorUserId: uuid("actor_user_id"),
    action: text("action").notNull(),
    entityType: text("entity_type"),
    entityId: uuid("entity_id"),
    reason: text("reason"),
    before: jsonb("before"),
    after: jsonb("after"),
    /** Legacy column (never written by the app role); "undone" is derived from undo_of_audit_id rows (ADR 0003). */
    undoneAt: timestamp("undone_at", { withTimezone: true }),
    /** Set on the compensating row that undoes another entry (append-only undo, ADR 0003). */
    undoOfAuditId: uuid("undo_of_audit_id"),
    createdAt: createdAt(),
  },
  (t) => [
    index("audit_ws_created_idx").on(t.workspaceId, t.createdAt),
    index("audit_ws_undo_idx").on(t.workspaceId, t.undoOfAuditId),
  ],
);

// ---------- Plan runs (D-019): persisted output of the last replan, read by GET /v1/plan ----------
export const mailExclusionKind = pgEnum("mail_exclusion_kind", ["sender", "domain", "label"]);

/** P2-13: senders, domains or labels the user excludes from ingestion (rules run before any AI call). */
export const mailExclusions = pgTable(
  "mail_exclusions",
  {
    id: id(),
    workspaceId: workspaceId(),
    kind: mailExclusionKind("kind").notNull(),
    value: text("value").notNull(),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex("mail_exclusions_uq").on(t.workspaceId, t.kind, t.value)],
);

export const planRuns = pgTable(
  "plan_runs",
  {
    id: id(),
    workspaceId: workspaceId(),
    planVersion: integer("plan_version").notNull(),
    horizonStart: timestamp("horizon_start", { withTimezone: true }).notNull(),
    horizonEnd: timestamp("horizon_end", { withTimezone: true }).notNull(),
    risks: jsonb("risks")
      .$type<{ taskId: string; slackHours: number; cause: string }[]>()
      .notNull()
      .default([]),
    conflicts: jsonb("conflicts")
      .$type<
        {
          code: string;
          taskIds: string[];
          details: Record<string, string | number>;
          alternatives: string[];
        }[]
      >()
      .notNull()
      .default([]),
    unscheduled: jsonb("unscheduled").$type<{ taskId: string; reason: string }[]>().notNull().default([]),
    /** What happened with the diff: applied safely, proposed, or nothing to do. */
    outcome: text("outcome").notNull(),
    proposalId: uuid("proposal_id"),
    createdAt: createdAt(),
  },
  (t) => [index("plan_runs_ws_id_idx").on(t.workspaceId, t.id)],
);

// ---------- Idempotency (docs/13, D-024) ----------
export const idempotencyKeys = pgTable(
  "idempotency_keys",
  {
    workspaceId: workspaceId(),
    key: text("key").notNull(),
    requestHash: text("request_hash").notNull(),
    statusCode: integer("status_code").notNull(),
    response: jsonb("response"),
    createdAt: createdAt(),
  },
  (t) => [primaryKey({ columns: [t.workspaceId, t.key] })],
);

// ---------- Notifications (F-13 AC2, D-020) ----------
export const notificationKind = pgEnum("notification_kind", [
  "digest",
  "risk",
  "proposals",
  "plan",
  "integration",
  /** Plan, trial and credit notices (D-061, [M6]): never count toward the daily alert cap. */
  "billing",
]);
export const notifications = pgTable(
  "notifications",
  {
    id: id(),
    workspaceId: workspaceId(),
    kind: notificationKind("kind").notNull(),
    /** Rendered in the default locale (fallback for e-mail digests); the UI renders `template` + `params`. */
    title: text("title").notNull(),
    body: text("body").notNull(),
    /** i18n template key (e.g. "risk.grouped") and its parameters. */
    template: text("template").notNull().default("generic"),
    params: jsonb("params").$type<Record<string, string | number>>().notNull().default({}),
    /** Entities grouped into this notification (ids only, never content). */
    refs: jsonb("refs").$type<{ type: string; id: string }[]>().notNull().default([]),
    /** YYYY-MM-DD in the user's time zone; used for the daily cap. */
    day: text("day").notNull(),
    readAt: timestamp("read_at", { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [index("notifications_ws_day_idx").on(t.workspaceId, t.day, t.createdAt)],
);

export const aiUsage = pgTable(
  "ai_usage",
  {
    id: id(),
    workspaceId: workspaceId(),
    operation: text("operation").notNull(), // 'extract_commitments' | 'capture_parse' | ...
    model: text("model").notNull(),
    inputTokens: integer("input_tokens").notNull().default(0),
    outputTokens: integer("output_tokens").notNull().default(0),
    cachedTokens: integer("cached_tokens").notNull().default(0),
    costMicroUsd: integer("cost_micro_usd").notNull().default(0),
    credits: real("credits").notNull().default(0),
    period: text("period").notNull(), // 'YYYY-MM'
    createdAt: createdAt(),
  },
  (t) => [index("ai_usage_ws_period_idx").on(t.workspaceId, t.period)],
);

export const valueEvents = pgTable(
  "value_events",
  {
    id: id(),
    workspaceId: workspaceId(),
    type: text("type").notNull(), // 'commitment_saved' | 'deadline_risk_flagged' | 'untracked_time_recovered'
    entityType: text("entity_type"),
    entityId: uuid("entity_id"),
    quantity: real("quantity"),
    unit: text("unit"),
    method: text("method").notNull(), // human-readable calculation method shown in UI
    createdAt: createdAt(),
  },
  (t) => [
    index("value_ws_type_idx").on(t.workspaceId, t.type, t.createdAt),
    // D-063: one event per live entity; undo deletes it, so re-approving can emit it again ([M7]).
    uniqueIndex("value_ws_type_entity_uq")
      .on(t.workspaceId, t.type, t.entityId)
      .where(sql`${t.entityId} is not null`),
  ],
);

// ---------- Billing ----------
export const subscriptions = pgTable(
  "subscriptions",
  {
    id: id(),
    workspaceId: workspaceId(),
    stripeCustomerId: text("stripe_customer_id"),
    stripeSubscriptionId: text("stripe_subscription_id"),
    plan: text("plan").notNull().default("trial"),
    status: text("status").notNull().default("trialing"),
    trialEndsAt: timestamp("trial_ends_at", { withTimezone: true }),
    currentPeriodEnd: timestamp("current_period_end", { withTimezone: true }),
    cancelAtPeriodEnd: boolean("cancel_at_period_end").notNull().default(false),
    /** 'month' | 'year' once a paid plan exists. */
    priceInterval: text("price_interval"),
    hasPaymentMethod: boolean("has_payment_method").notNull().default(false),
    /** Creation time of the last provider event applied: older events are recorded without effects ([H1]). */
    lastEventAt: timestamp("last_event_at", { withTimezone: true }),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex("subs_ws_uq").on(t.workspaceId)],
);

/** Defaults are the trial row of the plan catalogue (`@meri/core` PLANS.trial). */
export const entitlements = pgTable("entitlements", {
  workspaceId: workspaceId().primaryKey(),
  maxClients: integer("max_clients").notNull().default(25),
  aiCreditsMonthly: integer("ai_credits_monthly").notNull().default(300),
  retentionDays: integer("retention_days").notNull().default(90),
  features: jsonb("features").$type<string[]>().notNull().default([]),
  /** [H2] after a downgrade the previous (longer) retention holds until `retention_grace_until`. */
  previousRetentionDays: integer("previous_retention_days"),
  retentionGraceUntil: timestamp("retention_grace_until", { withTimezone: true }),
  updatedAt: updatedAt(),
});

/** Purchased credit packs (D-061); valid until the end of the calendar month they were bought in ([L16]). */
export const creditGrants = pgTable(
  "credit_grants",
  {
    id: id(),
    workspaceId: workspaceId(),
    credits: integer("credits").notNull(),
    period: text("period").notNull(), // 'YYYY-MM'
    pack: text("pack").notNull(),
    /** Provider event that paid for it: a replayed webhook can never grant twice. */
    sourceEventId: text("source_event_id").notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("credit_grants_source_uq").on(t.sourceEventId),
    index("credit_grants_ws_period_idx").on(t.workspaceId, t.period),
  ],
);

/** Per-workspace monthly margin rollup (D-062). Money in micro-USD; revenue is an estimate from the catalogue. */
export const billingRollups = pgTable(
  "billing_rollups",
  {
    id: id(),
    workspaceId: workspaceId(),
    period: text("period").notNull(),
    plan: text("plan").notNull(),
    charged: boolean("charged").notNull(),
    creditsUsed: real("credits_used").notNull().default(0),
    aiCostMicroUsd: bigint("ai_cost_micro_usd", { mode: "number" }).notNull().default(0),
    revenueMicroUsd: bigint("revenue_micro_usd", { mode: "number" }).notNull().default(0),
    infraCostMicroUsd: bigint("infra_cost_micro_usd", { mode: "number" }).notNull().default(0),
    paymentFeeMicroUsd: bigint("payment_fee_micro_usd", { mode: "number" }).notNull().default(0),
    grossMarginPct: real("gross_margin_pct"),
    marginAlarm: boolean("margin_alarm").notNull().default(false),
    computedAt: timestamp("computed_at", { withTimezone: true }).notNull(),
  },
  (t) => [uniqueIndex("billing_rollups_ws_period_uq").on(t.workspaceId, t.period)],
);

/** D-066 cancellation survey. The free-text comment never leaves the database (not in analytics, not in logs). */
export const cancellationFeedback = pgTable(
  "cancellation_feedback",
  {
    id: id(),
    workspaceId: workspaceId(),
    reason: text("reason").notNull(),
    comment: text("comment"),
    createdAt: createdAt(),
  },
  (t) => [index("cancel_feedback_ws_idx").on(t.workspaceId, t.createdAt)],
);

export const stripeEvents = pgTable("stripe_events", {
  id: text("id").primaryKey(), // Stripe event id => idempotency
  type: text("type").notNull(),
  processedAt: timestamp("processed_at", { withTimezone: true }).notNull().defaultNow(),
});

/**
 * Proof of an erasure without personal data (F-16, ADR 0007): the workspace id is only kept as a hash, so a restore
 * can re-apply the deletion without the receipt identifying anyone. Written only by `purge_workspace()`; the
 * application role has no privileges on it.
 */
export const deletionReceipts = pgTable("deletion_receipts", {
  subjectHash: text("subject_hash").primaryKey(),
  deletedAt: timestamp("deleted_at", { withTimezone: true }).notNull(),
  purgedAt: timestamp("purged_at", { withTimezone: true }).notNull().defaultNow(),
  rowsDeleted: integer("rows_deleted").notNull(),
  usersDeleted: integer("users_deleted").notNull(),
});

export const featureFlags = pgTable(
  "feature_flags",
  {
    id: id(),
    key: text("key").notNull(),
    workspaceId: uuid("workspace_id"), // null = global
    enabled: boolean("enabled").notNull().default(false),
  },
  (t) => [uniqueIndex("flags_key_ws_uq").on(t.key, t.workspaceId)],
);
